begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,pg_temp;
select extensions.no_plan();
insert into auth.users(id,email) values('11111111-1111-4111-8111-111111111111','plan-a@example.invalid'),('22222222-2222-4222-8222-222222222222','plan-b@example.invalid');
select extensions.ok(not has_function_privilege('anon','public.apply_plan_operation(uuid,text,text,text,text,uuid,jsonb,integer)','EXECUTE'),'anon plan writer denied');
select extensions.ok(has_function_privilege('authenticated','public.apply_plan_operation(uuid,text,text,text,text,uuid,jsonb,integer)','EXECUTE'),'authenticated plan capability');
select extensions.ok((select prosecdef and proowner='pickleup_api'::regrole and proconfig @> array['search_path=""'] from pg_proc where oid='public.apply_plan_operation(uuid,text,text,text,text,uuid,jsonb,integer)'::regprocedure),'plan writer narrow owner and empty search path');
select extensions.ok((select not rolcanlogin and not rolbypassrls from pg_roles where rolname='pickleup_api'),'API role no login or bypass');
select extensions.ok(not has_schema_privilege('pickleup_api','public','CREATE') and not has_schema_privilege('pickleup_api','pickleup_private','CREATE'),'transient CREATE revoked');
select extensions.ok(not has_table_privilege('authenticated','public.personal_plans','INSERT,UPDATE,DELETE') and not has_table_privilege('authenticated','public.user_selections','INSERT,UPDATE,DELETE'),'no client DML');
select extensions.ok(not has_table_privilege('pickleup_api','pickleup_private.sync_operation_epochs','UPDATE,DELETE'),'shared epoch ledger append only');
select extensions.ok((select bool_and(relrowsecurity and relforcerowsecurity) from pg_class where oid in ('public.personal_plans'::regclass,'public.user_selections'::regclass)),'plan and selection FORCE RLS retained');
set local role authenticated;
select set_config('request.jwt.claims','{}',true);
select extensions.is(public.apply_plan_operation('00000001-3333-4333-8333-333333333333','personal_plans','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','put','0','eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee'::uuid,'{}'::jsonb,1)->>'status','auth_required','no caller cannot write');
select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-111111111111","role":"authenticated"}',true);
select set_config('test.plan_epoch',public.prepare_sync()->>'epoch',true);
select set_config('test.plan_payload','{"source": "basic", "schema_version": 1, "level_band": "1.0\u20132.0", "plan_snapshot": {"id": "synthetic-plan", "version": "2.4", "createdAt": "2026-01-01T10:00:00Z", "level": "1.0\u20132.0", "scores": {"serve": 12, "return": 12, "dink": 12, "volley": 12, "position": 12, "strategy": 12}, "exercises": [{"id": "serve-1", "skill": "serve", "name": "Synthetic drill", "setup": "Synthetic", "instructions": "Synthetic", "measure": "Synthetic", "mistake": "Synthetic", "skillName": "serve", "minutes": 12, "baseline": 12, "target": 15}, {"id": "return-1", "skill": "return", "name": "Synthetic drill", "setup": "Synthetic", "instructions": "Synthetic", "measure": "Synthetic", "mistake": "Synthetic", "skillName": "return", "minutes": 12, "baseline": 12, "target": 15}, {"id": "dink-1", "skill": "dink", "name": "Synthetic drill", "setup": "Synthetic", "instructions": "Synthetic", "measure": "Synthetic", "mistake": "Synthetic", "skillName": "dink", "minutes": 15, "baseline": 12, "target": 15}], "minutes": {"warmup": 10, "drills": [12, 12, 15], "assessment": 6, "cooldown": 5}, "checkpoint": {"skill": "serve", "baseline": 12, "target": 15, "attempts": 20}, "completedAt": null, "checkScore": null}}',true);
select extensions.is(public.apply_plan_operation('00000001-3333-4333-8333-333333333333','personal_plans','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','put','0',current_setting('test.plan_epoch')::uuid,'{}'::jsonb,2)->>'status','upgrade_required','wire protocol checked');
select extensions.is(public.apply_plan_operation('00000001-3333-4333-8333-333333333333','personal_plans','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','put','0','eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee'::uuid,'{}'::jsonb,1)->>'status','reset_required','wrong epoch cannot create');
select extensions.is(public.apply_plan_operation('00000001-3333-4333-8333-333333333333','user_preferences','self','put','0',current_setting('test.plan_epoch')::uuid,'{}'::jsonb,1)->>'status','invalid','capability excludes mutable data');
select extensions.is(public.apply_plan_operation('00000001-3333-4333-8333-333333333333','personal_plans','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','put','0',current_setting('test.plan_epoch')::uuid,'[]'::jsonb,1)->>'status','invalid','non object is domain error');
select extensions.is(public.apply_plan_operation('00000001-3333-4333-8333-333333333333','personal_plans','AAAAAAAA-AAAA-4AAA-8AAA-AAAAAAAAAAAA','put','0',current_setting('test.plan_epoch')::uuid,'{}'::jsonb,1)->>'status','invalid','canonical UUID key required');
select extensions.is(public.apply_plan_operation('00000001-3333-4333-8333-333333333333','user_selections','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','put','0',current_setting('test.plan_epoch')::uuid,'{}'::jsonb,1)->>'status','invalid','selection is singleton self');
select extensions.is(public.apply_plan_operation('00000001-3333-4333-8333-333333333333','personal_plans','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','put','0',current_setting('test.plan_epoch')::uuid,current_setting('test.plan_payload')::jsonb,1)->>'status','applied','create immutable plan');
select extensions.is(public.apply_plan_operation('00000001-3333-4333-8333-333333333333','personal_plans','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','put','0',current_setting('test.plan_epoch')::uuid,current_setting('test.plan_payload')::jsonb,1)->>'replayed','true','exact replay stable');
select extensions.is(public.apply_plan_operation('00000002-3333-4333-8333-333333333333','personal_plans','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','put','1',current_setting('test.plan_epoch')::uuid,jsonb_build_object('plan_snapshot',current_setting('test.plan_payload')::jsonb->'plan_snapshot'),1)->>'code','immutable_plan_fields','even equal snapshot patch denied');
select extensions.is(public.apply_plan_operation('00000002-3333-4333-8333-333333333333','personal_plans','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','put','1',current_setting('test.plan_epoch')::uuid,'{"check_score":12}'::jsonb,1)->>'code','operation_id_reused','rejected patch cannot change command');
select extensions.is(public.apply_plan_operation('00000003-3333-4333-8333-333333333333','personal_plans','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','put','1',current_setting('test.plan_epoch')::uuid,'{"check_score":15}'::jsonb,1)->>'status','applied','results update via CAS');
select extensions.is(public.apply_plan_operation('00000004-3333-4333-8333-333333333333','personal_plans','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','put','1',current_setting('test.plan_epoch')::uuid,'{"check_score":16}'::jsonb,1)->>'status','conflict','stale revision conflicts in HTTP200 domain');
select extensions.ok((select plan_snapshot=current_setting('test.plan_payload')::jsonb->'plan_snapshot' from public.personal_plans),'result update preserves snapshot');
select extensions.is(public.apply_plan_operation('00000005-3333-4333-8333-333333333333','user_selections','self','put','0',current_setting('test.plan_epoch')::uuid,'{"selected_personal_plan_id":"aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa"}'::jsonb,1)->>'status','applied','select own live plan');
select extensions.is(public.apply_plan_operation('00000006-3333-4333-8333-333333333333','personal_plans','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','delete','2',current_setting('test.plan_epoch')::uuid,'{}'::jsonb,1)->>'status','invalid','selected plan cannot delete');
select extensions.is(public.apply_plan_operation('00000007-3333-4333-8333-333333333333','user_selections','self','delete','1',current_setting('test.plan_epoch')::uuid,'{}'::jsonb,1)->>'status','applied','clear selection with tombstone');
select extensions.is(public.apply_plan_operation('00000008-3333-4333-8333-333333333333','personal_plans','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','delete','2',current_setting('test.plan_epoch')::uuid,'{}'::jsonb,1)->>'status','applied','unselected plan can tombstone');
select extensions.is(public.apply_plan_operation('00000009-3333-4333-8333-333333333333','user_selections','self','restore','2',current_setting('test.plan_epoch')::uuid,'{"selected_personal_plan_id":"aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa"}'::jsonb,1)->>'status','invalid','deleted target cannot select');
select extensions.is(public.apply_plan_operation('0000000a-3333-4333-8333-333333333333','personal_plans','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','put','3',current_setting('test.plan_epoch')::uuid,'{"check_score":16}'::jsonb,1)->>'status','conflict','put does not resurrect');
select extensions.is(public.apply_plan_operation('0000000b-3333-4333-8333-333333333333','personal_plans','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','restore','3',current_setting('test.plan_epoch')::uuid,'{}'::jsonb,1)->>'status','applied','explicit plan restore');
select extensions.is(public.apply_plan_operation('0000000c-3333-4333-8333-333333333333','user_selections','self','restore','2',current_setting('test.plan_epoch')::uuid,'{"selected_personal_plan_id":"aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa"}'::jsonb,1)->>'status','applied','explicit selection restore after plan');
select extensions.is((select count(*)::text from public.practice_checkins),'0','plan results never create attendance');
select set_config('request.jwt.claims','{"sub":"22222222-2222-4222-8222-222222222222","role":"authenticated"}',true);
select set_config('test.plan_epoch',public.prepare_sync()->>'epoch',true);
select extensions.is((select count(*)::text from public.personal_plans),'0','B sees no A plans');
select extensions.is(public.apply_plan_operation('0000000d-3333-4333-8333-333333333333','user_selections','self','put','0',current_setting('test.plan_epoch')::uuid,'{"selected_personal_plan_id":"aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa"}'::jsonb,1)->>'status','invalid','B cannot select A plan');
select extensions.is(public.apply_plan_operation('0000000e-3333-4333-8333-333333333333','personal_plans','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','put','4',current_setting('test.plan_epoch')::uuid,'{"check_score":1}'::jsonb,1)->>'status','conflict','B cannot update A revision');
reset role;
select * from extensions.finish();
rollback;
